/* EARTHUS V2 — imagery-only geographic polar geometry fill.
 * Fills only the extreme-pole geometry gap left by the terrain service.
 * Source pixels are NASA GIBS EPSG:4326 imagery. No elevation is invented.
 */
const WMS='https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi';
const EDGE_LAT=81.75;
const HEIGHT_M=160;
const LAYERS=Object.freeze(['BlueMarble_ShadedRelief','BlueMarble_ShadedRelief_Bathymetry','BlueMarble_NextGeneration']);
function urlFor(north,layer){const south=north?EDGE_LAT:-90,northLat=north?90:-EDGE_LAT,u=new URL(WMS);u.search=new URLSearchParams({service:'WMS',version:'1.1.1',request:'GetMap',styles:'',layers:layer,srs:'EPSG:4326',bbox:`-180,${south},180,${northLat}`,width:'1536',height:'576',format:'image/jpeg',transparent:'false'}).toString();return u.href}
async function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.decoding='async';image.onload=()=>image.naturalWidth>=1024&&image.naturalHeight>=256?resolve(image):reject(new Error('POLAR_GEOGRAPHIC_IMAGE_DIMENSION_GATE'));image.onerror=()=>reject(new Error('POLAR_GEOGRAPHIC_IMAGE_DECODE_FAILED'));image.src=url})}
function imageSignal(image){const cv=document.createElement('canvas');cv.width=384;cv.height=128;const cx=cv.getContext('2d',{willReadFrequently:true});if(!cx)throw new Error('POLAR_GEOGRAPHIC_CANVAS_CONTEXT');cx.drawImage(image,0,0,cv.width,cv.height);const d=cx.getImageData(0,0,cv.width,cv.height).data,values=[];let sum=0,sum2=0,n=0,dark=0,bright=0;for(let y=0;y<cv.height;y+=2)for(let x=0;x<cv.width;x+=2){const i=(y*cv.width+x)*4,l=(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2])/255;values.push(l);sum+=l;sum2+=l*l;n++;if(l<.012)dark++;if(l>.18)bright++}values.sort((a,b)=>a-b);const mean=sum/Math.max(1,n),std=Math.sqrt(Math.max(0,sum2/Math.max(1,n)-mean*mean)),p10=values[Math.floor(values.length*.1)]||0,p90=values[Math.floor(values.length*.9)]||0,dynamicRange=p90-p10;return{mean,std,dynamicRange,darkRatio:dark/Math.max(1,n),brightRatio:bright/Math.max(1,n),score:mean*.45+std*1.5+dynamicRange*.8+bright/Math.max(1,n)*.25}}
function signalUsable(s){return s.darkRatio<=.94&&s.std>=.004&&s.dynamicRange>=.008}
function signalStrong(s){return s.darkRatio<=.82&&s.std>=.018&&s.dynamicRange>=.05}
async function loadBest(north){const usable=[];let last=null;for(const layer of LAYERS){const url=urlFor(north,layer);try{const image=await loadImage(url),signal=imageSignal(image);if(!signalUsable(signal))throw new Error(`POLAR_GEOGRAPHIC_IMAGE_SIGNAL:${signal.mean.toFixed(4)}:${signal.std.toFixed(4)}:${signal.dynamicRange.toFixed(4)}`);const candidate={image,layer,url,signal};usable.push(candidate);if(signalStrong(signal))return Object.freeze(candidate)}catch(error){last=error}}if(!usable.length)throw new Error(`POLAR_GEOGRAPHIC_NO_GIBS_LAYER:${last?.message||'unknown'}`);usable.sort((a,b)=>b.signal.score-a.signal.score);return Object.freeze(usable[0])}
function rectangle(C,north){return C.Rectangle.fromDegrees(-180,north?EDGE_LAT:-90,180,north?90:-EDGE_LAT)}
function buildPrimitive(viewer,C,north,asset){const material=C.Material.fromType('Image',{image:asset.image,repeat:new C.Cartesian2(1,1),color:C.Color.WHITE}),geometry=new C.RectangleGeometry({rectangle:rectangle(C,north),height:HEIGHT_M,granularity:C.Math.toRadians(.5),vertexFormat:C.EllipsoidSurfaceAppearance.VERTEX_FORMAT}),appearance=new C.EllipsoidSurfaceAppearance({aboveGround:true,faceForward:true,translucent:false,material});return viewer.scene.primitives.add(new C.Primitive({geometryInstances:new C.GeometryInstance({geometry}),appearance,allowPicking:false,asynchronous:false}))}
export class PolarGeographicCapRuntime{
 constructor({viewer,Cesium}={}){if(!viewer||viewer.isDestroyed?.())throw new Error('POLAR_GEOGRAPHIC_VIEWER_REQUIRED');this.viewer=viewer;this.C=Cesium||globalThis.Cesium;this.primitives=[];this.sources=[];this.truth='UNINITIALIZED';this.generation=0}
 async load({force=false}={}){const generation=++this.generation;if(this.primitives.length&&!force)return this.truth;this.dispose({preserveGeneration:true});this.truth='LOADING';const assets=await Promise.all([true,false].map(async north=>({north,asset:await loadBest(north)})));if(generation!==this.generation)return null;for(const {north,asset} of assets){const primitive=buildPrimitive(this.viewer,this.C,north,asset);this.primitives.push(primitive);this.sources.push(Object.freeze({hemisphere:north?'NORTH':'SOUTH',epsg:'EPSG:4326',layer:asset.layer,edgeLatitudeDeg:north?EDGE_LAT:-EDGE_LAT,truthClass:'NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY',imageSignal:Object.freeze(asset.signal),geometryClass:'CESIUM_RECTANGLE_GEOMETRY',granularityDeg:.5}))}this.truth='NASA_GIBS_GEOGRAPHIC_POLAR_HOLE_FILL_IMAGERY_ONLY';this.viewer.scene.requestRender();return this.truth}
 setVisible(show){for(const p of this.primitives)p.show=!!show;this.viewer.scene.requestRender()}
 getTruth(){return this.truth}
 getSources(){return Object.freeze([...this.sources])}
 dispose({preserveGeneration=false}={}){if(!preserveGeneration)this.generation++;for(const p of this.primitives)try{this.viewer.scene.primitives.remove(p)}catch(_){}this.primitives=[];this.sources=[];this.truth='UNINITIALIZED'}
}
